def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def edge_segment(r):
        cells = [c for c, v in enumerate(grid[r]) if v != bg]
        if not cells:
            return None
        color = grid[r][cells[0]]
        cols = [c for c in cells if grid[r][c] == color]
        return color, min(cols), max(cols)

    top = edge_segment(0)
    bottom = edge_segment(h - 1)
    if top is None or bottom is None:
        return out

    bar_color = top[0]
    dot_colors = [v for row in grid for v in row if v != bg and v != bar_color]
    if not dot_colors:
        return out
    dot_color = Counter(dot_colors).most_common(1)[0][0]

    _, t0, t1 = top
    _, b0, b1 = bottom
    length = min(t1 - t0 + 1, b1 - b0 + 1)

    # Dots on either edge's span select the matching offset on both spans.
    active = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == dot_color:
                if t0 <= c < t0 + length:
                    active.add(c - t0)
                if b0 <= c < b0 + length:
                    active.add(c - b0)

    def paint(r, c, step):
        rr = r + step
        while 0 <= rr < h:
            v = grid[rr][c]
            if v == dot_color:
                out[rr][c] = 4
                break
            if v != bg:
                break
            out[rr][c] = dot_color
            rr += step

    for offset in active:
        paint(0, t0 + offset, 1)
        paint(h - 1, b0 + offset, -1)

    return out
